import os
from typing import List, Dict, Any, Optional

from google.cloud import texttospeech


_LANGUAGE_VOICE_HINTS = {
    "en-US": ["en-US-Wavenet-D", "en-US-Wavenet-F", "en-US-Neural2-D", "en-US-Neural2-F"],
    "en-GB": ["en-GB-Wavenet-B", "en-GB-Wavenet-D", "en-GB-Neural2-B", "en-GB-Neural2-D"],
    "fr-FR": ["fr-FR-Wavenet-B", "fr-FR-Wavenet-D", "fr-FR-Neural2-B", "fr-FR-Neural2-D"],
    "de-DE": ["de-DE-Wavenet-B", "de-DE-Wavenet-D", "de-DE-Neural2-B", "de-DE-Neural2-D"],
    "es-ES": ["es-ES-Wavenet-B", "es-ES-Wavenet-C", "es-ES-Neural2-B", "es-ES-Neural2-C"],
    "it-IT": ["it-IT-Wavenet-B", "it-IT-Wavenet-C", "it-IT-Neural2-B", "it-IT-Neural2-C"],
    "ja-JP": ["ja-JP-Wavenet-B", "ja-JP-Wavenet-D", "ja-JP-Neural2-B", "ja-JP-Neural2-D"],
    "ko-KR": ["ko-KR-Wavenet-B", "ko-KR-Wavenet-D", "ko-KR-Neural2-B", "ko-KR-Neural2-D"],
    "pt-BR": ["pt-BR-Wavenet-B", "pt-BR-Wavenet-D", "pt-BR-Neural2-B", "pt-BR-Neural2-D"],
    "hi-IN": ["hi-IN-Wavenet-A", "hi-IN-Wavenet-D", "hi-IN-Neural2-A", "hi-IN-Neural2-D"],
}


def list_voices_for_locale(locale: str) -> List[Dict[str, Any]]:
    """
    List voices for a target locale using Google Cloud Text-to-Speech.

    Returns a list of dictionaries with voice metadata.
    """
    client = texttospeech.TextToSpeechClient()
    response = client.list_voices(language_code=locale)

    preferred_names = set(_LANGUAGE_VOICE_HINTS.get(locale, []))
    voices = []

    for voice in response.voices:
        if locale in voice.language_codes:
            voices.append(
                {
                    "name": voice.name,
                    "language_codes": list(voice.language_codes),
                    "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name
                    if isinstance(voice.ssml_gender, int)
                    else str(voice.ssml_gender),
                    "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
                    "preferred": voice.name in preferred_names,
                }
            )

    voices.sort(key=lambda v: (not v["preferred"], v["name"]))
    return voices


def select_voice_for_locale(locale: str, preferred_voice_name: Optional[str] = None) -> Optional[Dict[str, Any]]:
    """
    Select a single best voice for a target locale.

    Priority:
      1) preferred_voice_name if valid for locale
      2) a provider-specific curated hint for the locale
      3) first available voice for locale
    """
    voices = list_voices_for_locale(locale)
    if not voices:
        return None

    if preferred_voice_name:
        for voice in voices:
            if voice["name"] == preferred_voice_name:
                return voice

    for voice_name in _LANGUAGE_VOICE_HINTS.get(locale, []):
        for voice in voices:
            if voice["name"] == voice_name:
                return voice

    return voices[0]


if __name__ == "__main__":
    locale = os.environ.get("TTS_LOCALE", "en-US")
    selected = select_voice_for_locale(locale)
    if selected is None:
        print(f"No voices found for locale: {locale}")
    else:
        print(selected)
